/**
 * MeanMenu - Mobile Navigation jQuery Plugin
 * A simple mobile navigation menu plugin
 */
(function($) {
    "use strict";
    
    $.meanmenu = function(options) {
        var defaults = {
            meanMenuTarget: jQuery(this),
            meanMenuContainer: 'body',
            meanMenuClose: "X",
            meanMenuCloseSize: "18px",
            meanMenuOpen: "<span></span><span></span><span></span>",
            meanRevealPosition: "right",
            meanRevealPositionDistance: "0",
            meanRevealColour: "",
            meanScreenWidth: "480",
            meanNavPush: "",
            meanShowChildren: true,
            meanExpandableChildren: true,
            meanExpand: "+",
            meanContract: "-",
            meanRemoveAttrs: false,
            onePage: false,
            meanDisplay: "block",
            removeElements: ""
        };
        
        options = $.extend(defaults, options);
        
        return this.each(function() {
            var meanMenu = options.meanMenuTarget;
            var meanContainer = options.meanMenuContainer;
            var meanMenuClose = options.meanMenuClose;
            var meanMenuCloseSize = options.meanMenuCloseSize;
            var meanMenuOpen = options.meanMenuOpen;
            var meanRevealPosition = options.meanRevealPosition;
            var meanRevealPositionDistance = options.meanRevealPositionDistance;
            var meanRevealColour = options.meanRevealColour;
            var meanScreenWidth = options.meanScreenWidth;
            var meanNavPush = options.meanNavPush;
            var meanShowChildren = options.meanShowChildren;
            var meanExpandableChildren = options.meanExpandableChildren;
            var meanExpand = options.meanExpand;
            var meanContract = options.meanContract;
            var meanRemoveAttrs = options.meanRemoveAttrs;
            var onePage = options.onePage;
            var meanDisplay = options.meanDisplay;
            var removeElements = options.removeElements;
            
            var meanReveal = $('<div class="meanmenu-reveal"></div>');
            var meanNav = $('<nav class="mean-nav"></nav>');
            
            // Build the menu
            meanMenu.before(meanReveal);
            meanNav.appendTo(meanContainer);
            meanReveal.html(meanMenuOpen);
            
            // Hide menu by default
            meanNav.hide();
            
            // Toggle menu
            meanReveal.on('click', function(e) {
                e.preventDefault();
                if (meanNav.is(':visible')) {
                    meanMenu.meanmenu({
                        meanMenuClose: meanMenuClose
                    });
                    meanNav.hide();
                } else {
                    meanMenu.meanmenu({
                        meanMenuClose: meanMenuClose
                    });
                    meanNav.show();
                }
            });
            
            // Handle meanShowChildren
            if (meanShowChildren) {
                meanNav.find('li ul').show();
            } else {
                meanNav.find('li ul').hide();
            }
            
            // Handle expandable children
            if (meanExpandableChildren) {
                meanNav.find('li ul').each(function() {
                    var $ul = $(this);
                    if ($ul.children().length) {
                        var $children = $ul.children('a');
                        var $expander = $('<span class="mean-expand">' + meanExpand + '</span>');
                        $children.wrap('<div class="mean-child">');
                        $expander.on('click', function(e) {
                            e.preventDefault();
                            var $parent = $(this).parent();
                            if ($parent.hasClass('mean-expand-active')) {
                                $parent.removeClass('mean-expand-active');
                                $ul.hide();
                                $(this).html(meanExpand);
                            } else {
                                $parent.addClass('mean-expand-active');
                                $ul.show();
                                $(this).html(meanContract);
                            }
                        });
                        $children.after($expander);
                    }
                });
            }
            
            // Responsive
            function meanMenu() {
                if ($(window).width() <= meanScreenWidth) {
                    meanReveal.show();
                    meanNav.show();
                } else {
                    meanReveal.hide();
                    meanNav.hide();
                }
            }
            
            meanMenu();
            $(window).resize(meanMenu);
        });
    };
})(jQuery);
